-- Repair the readings.id identity sequence without changing existing readings.
--
-- Preconditions:
--   1. Create and verify a fresh PostgreSQL backup.
--   2. Stop the backend so no application writes occur during this repair.
--   3. Confirm duplicate_groups = 0 before applying.
--
-- This is intentionally separate from the larger partition migration. The
-- current table uses GENERATED BY DEFAULT AS IDENTITY, so do not attach a
-- normal DEFAULT to the identity column. This script reseeds the existing
-- identity-owned sequence above MAX(id) and preserves all existing row IDs.

BEGIN;

LOCK TABLE readings IN SHARE ROW EXCLUSIVE MODE;

CREATE SEQUENCE IF NOT EXISTS readings_id_seq;

SELECT setval(
    'readings_id_seq',
    (SELECT COALESCE(MAX(id), 0) + 1 FROM readings),
    false
);

-- The identity column already owns and uses readings_id_seq. Do not attach a
-- normal DEFAULT or alter the identity definition here.

COMMIT;

